import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.Drp2S_UI.js";const m=JSON.parse('{"title":"能力与支持边界","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1792752159000}'),o={name:"guide/features.md"};function h(n,t,l,s,i,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="能力与支持边界" tabindex="-1">能力与支持边界 <a class="header-anchor" href="#能力与支持边界" aria-label="Permalink to &quot;能力与支持边界&quot;">​</a></h1><p>本页概述当前独立 fork 的能力，具体字段以<a href="./option.html">配置</a>和命令参考为准。继承自上游的功能与新增排版能力分别在<a href="./fork-and-differences.html">项目关系</a>列出，避免把既有功能误认为本 fork 原创。</p><table tabindex="0"><thead><tr><th>领域</th><th>当前支持</th><th>接入边界</th></tr></thead><tbody><tr><td>文字排版</td><td>HarfBuzz 整形、BiDi、复杂文字、真实字体覆盖与字形轮廓</td><td>不承诺所有文种、样式与 emoji 完整验证；需字体文件</td></tr><tr><td>富文本</td><td>字体字号、粗斜体、颜色、高亮、上下标、装饰、标题、对齐、列表、缩进、行距与段距</td><td>字重/样式需要实际 face；字体度量可能改变分页</td></tr><tr><td>页面</td><td>分页/连页、页边距、分栏、页眉页脚、页码、行号、边框、水印</td><td>页面固定 Canvas；DOM 工具层仍存在</td></tr><tr><td>表格</td><td>行列操作、合并拆分、边框背景、对齐、跨页分片</td><td>复杂表格仍需按业务数据回归</td></tr><tr><td>图片与对象</td><td>图片、浮动图、链接、公式、日期、Tab、分页符和内容块</td><td>外部资源受加载、CORS 与导出限制</td></tr><tr><td>表单控件</td><td>文本、数字、下拉、单选、复选、日期、嵌套、禁用与级联校验</td><td>详见控件 API；工具界面由宿主组装</td></tr><tr><td>编辑交互</td><td>选区、光标、撤销重做、搜索替换、快捷键、右键菜单、拖拽</td><td>光标/删除语义可配置，UI 方向不等于内容方向</td></tr><tr><td>文档业务</td><td>批注、留痕、区域、目录、宏、国际化与模式切换</td><td>上游插件需单独验证</td></tr><tr><td>字体管理</td><td>TTF/OTF/WOFF/WOFF2、缺字报告与事件、Bunny 基本字体自动下载</td><td>默认开启；可离线关闭并手动提供；不是完整字库</td></tr><tr><td>导出与打印</td><td>JSON、HTML/文字查询、Canvas PNG 页面与浏览器图片打印</td><td>无独立 SVG 页面导出、无原生矢量 PDF 保证</td></tr><tr><td>分发</td><td>ESM 包根导出、TypeScript 声明、异步 ready</td><td>无 UMD / require / 内部深路径兼容</td></tr></tbody></table><h2 id="性能与实验项" tabindex="-1">性能与实验项 <a class="header-anchor" href="#性能与实验项" aria-label="Permalink to &quot;性能与实验项&quot;">​</a></h2><p><code>lab.incrementalCompute</code> 默认关闭。它复用未变化段落，仍执行全局流、分页和位置更新；不是只修改 Canvas 局部像素的通用优化。T23/T24 已完成回归，但性能仍有后续工作，开启增量不保证更快。参见<a href="./lab.html">增量边界</a>和<a href="./native-release-acceptance.html">最终验收</a>。</p><h2 id="暂缓与不提供的能力" tabindex="-1">暂缓与不提供的能力 <a class="header-anchor" href="#暂缓与不提供的能力" aria-label="Permalink to &quot;暂缓与不提供的能力&quot;">​</a></h2><p>SVG 页面后端与独立 SVG 导出暂缓，仅保留<a href="./harfbuzz-svg-assessment.html">设计评估</a>。没有引擎切换配置或 legacy 回退。安装包本身不提供业务服务器、协同 CRDT、原生 Word/PDF 排版引擎，也不自动安装上游插件。文档中的未来设计与历史迁移步骤不代表当前公开 API。</p><p>最新输入性能优化使用独立的 <code>lab.performanceProfile</code>；配置与边界见<a href="./lab.html">实验特性</a>，实测前后对比见 <a href="./benchmark.html">Benchmark</a>。</p>',8)])])}const p=d(o,[["render",h]]);export{m as __pageData,p as default};
